import express from 'express';
import session from 'express-session';
import Database from 'better-sqlite3';
import bcrypt from 'bcryptjs';
import multer from 'multer';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import fs from 'node:fs';

const EMBEDDED_APP_JS = Buffer.from('', 'base64').toString('utf8');
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
const PORT = Number(process.env.PORT || 3000);
const isProd = process.env.NODE_ENV === 'production';
if (isProd && !process.env.SESSION_SECRET) throw new Error('SESSION_SECRET environment variable is required in production');
const db = new Database(process.env.DB_PATH || path.join(__dirname, 'telephone-sy.db'));
db.pragma('journal_mode = WAL'); db.pragma('foreign_keys = ON');
db.exec(`
CREATE TABLE IF NOT EXISTS users (
 id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, phone TEXT NOT NULL UNIQUE,
 password_hash TEXT NOT NULL, shop TEXT, city TEXT, region TEXT, role TEXT NOT NULL DEFAULT 'user',
 is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS listings (
 id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 brand TEXT NOT NULL, model TEXT NOT NULL, currency TEXT NOT NULL CHECK(currency IN ('USD','SYP')),
 price REAL NOT NULL CHECK(price > 0), storage_gb INTEGER NOT NULL DEFAULT 128, ram_gb INTEGER,
 condition TEXT NOT NULL CHECK(condition IN ('new','used')), city TEXT NOT NULL, region TEXT,
 seller_name TEXT NOT NULL, contact_phone TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',
 is_sold INTEGER NOT NULL DEFAULT 0, views INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS listing_images (
 id INTEGER PRIMARY KEY AUTOINCREMENT, listing_id INTEGER NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
 path TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS favorites (
 user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 listing_id INTEGER NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id, listing_id)
);
CREATE TABLE IF NOT EXISTS reports (
 id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 listing_id INTEGER NOT NULL, reason TEXT NOT NULL, details TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'open',
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS admin_actions (
 id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id INTEGER NOT NULL, action TEXT NOT NULL,
 target_type TEXT NOT NULL, target_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_listings_created ON listings(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_listings_owner ON listings(owner_id);
`);

// Optional first admin: set ADMIN_PHONE and ADMIN_PASSWORD before first startup.
if (process.env.ADMIN_PHONE && process.env.ADMIN_PASSWORD) {
  const phone = process.env.ADMIN_PHONE.trim();
  const found = db.prepare('SELECT id FROM users WHERE phone=?').get(phone);
  if (!found) db.prepare('INSERT INTO users(name,phone,password_hash,role) VALUES(?,?,?,?)')
    .run('مدير Telephone-SY', phone, bcrypt.hashSync(process.env.ADMIN_PASSWORD, 12), 'admin');
}

app.disable('x-powered-by');
app.use((req,res,next)=>{res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('Referrer-Policy','same-origin');res.setHeader('X-Frame-Options','DENY');next();});
app.use(express.json({limit:'150kb'}));
app.use(express.urlencoded({extended:false,limit:'150kb'}));
app.use(session({name:'tsy.sid',secret:process.env.SESSION_SECRET || crypto.randomBytes(32).toString('hex'),resave:false,saveUninitialized:false,cookie:{httpOnly:true,sameSite:'lax',secure:isProd,maxAge:7*24*60*60*1000}}));
app.use('/uploads',express.static(path.join(__dirname,'uploads'),{fallthrough:false,maxAge:isProd?'1d':0}));
app.get('/static/app.js', (req, res) => { res.type('application/javascript; charset=utf-8').send(EMBEDDED_APP_JS); });
app.use('/static',express.static(path.join(__dirname,'public/static')));
app.use(express.static(path.join(__dirname,'public')));

const phoneOk = v => typeof v === 'string' && /^[+0-9]{7,16}$/.test(v.trim());
const publicUser = u => ({id:u.id,name:u.name,phone:u.phone,shop:u.shop,city:u.city,region:u.region,role:u.role,is_active:!!u.is_active});
const currentUser = req => req.session.userId ? db.prepare('SELECT * FROM users WHERE id=?').get(req.session.userId) : null;
function auth(req,res,next){const u=currentUser(req);if(!u||!u.is_active)return res.status(401).json({detail:'يرجى تسجيل الدخول أولاً'});req.user=u;next();}
function admin(req,res,next){if(req.user?.role!=='admin')return res.status(403).json({detail:'هذه العملية للمشرفين فقط'});next();}
function audit(user,action,type,id){db.prepare('INSERT INTO admin_actions(admin_id,action,target_type,target_id) VALUES(?,?,?,?)').run(user.id,action,type,String(id));}
function listingRow(id){return db.prepare(`SELECT l.*,u.name AS owner_name FROM listings l JOIN users u ON u.id=l.owner_id WHERE l.id=?`).get(id);}
function listingOut(row){if(!row)return null;const images=db.prepare('SELECT path FROM listing_images WHERE listing_id=? ORDER BY id').all(row.id).map(x=>x.path);return {...row,title:`${row.brand} ${row.model}`,owner_id:row.owner_id,seller_name:row.seller_name,contact_phone:row.contact_phone,images,is_sold:!!row.is_sold,views:row.views,created_at:row.created_at};}
function ownedListing(req,res,next){const row=listingRow(Number(req.params.id));if(!row)return res.status(404).json({detail:'الإعلان غير موجود'});if(row.owner_id!==req.user.id&&req.user.role!=='admin')return res.status(403).json({detail:'لا تملك صلاحية هذا الإعلان'});req.listing=row;next();}

app.get('/api/health',(req,res)=>res.json({status:'ok',database:'connected'}));
app.get('/api/auth/me',(req,res)=>{const u=currentUser(req);if(!u||!u.is_active)return res.status(401).json({detail:'غير مسجل الدخول'});res.json(publicUser(u));});
app.post('/api/auth/register',(req,res)=>{
 const {name,phone,password,shop=null,city=null,region=null}=req.body||{};
 if(typeof name!=='string'||name.trim().length<2||name.length>120)return res.status(400).json({detail:'الاسم مطلوب (حرفان على الأقل)'});
 if(!phoneOk(phone))return res.status(400).json({detail:'رقم الهاتف غير صالح'});
 if(typeof password!=='string'||password.length<10||password.length>200)return res.status(400).json({detail:'كلمة المرور يجب أن تكون 10 أحرف على الأقل'});
 try{const info=db.prepare('INSERT INTO users(name,phone,password_hash,shop,city,region) VALUES(?,?,?,?,?,?)').run(name.trim(),phone.trim(),bcrypt.hashSync(password,12),typeof shop==='string'?shop.slice(0,120):null,typeof city==='string'?city.slice(0,80):null,typeof region==='string'?region.slice(0,80):null);req.session.userId=Number(info.lastInsertRowid);res.status(201).json(publicUser(currentUser(req)));}catch(e){if(String(e.code).includes('SQLITE_CONSTRAINT'))return res.status(409).json({detail:'رقم الهاتف مسجل مسبقاً'});throw e;}
});
app.post('/api/auth/login',(req,res)=>{const {phone,password}=req.body||{};if(typeof phone!=='string'||typeof password!=='string')return res.status(400).json({detail:'أدخل رقم الهاتف وكلمة المرور'});const u=db.prepare('SELECT * FROM users WHERE phone=?').get(phone.trim());if(!u||!bcrypt.compareSync(password,u.password_hash)||!u.is_active)return res.status(401).json({detail:'رقم الهاتف أو كلمة المرور غير صحيحة'});req.session.regenerate(err=>{if(err)return res.status(500).json({detail:'تعذر إنشاء الجلسة'});req.session.userId=u.id;res.json(publicUser(u));});});
app.post('/api/auth/logout',(req,res)=>req.session.destroy(()=>{res.clearCookie('tsy.sid');res.status(204).end();}));

app.get('/api/listings',(req,res)=>{
 const {q,brand,city,region,condition,currency,min_price,max_price,sort='newest',seller_name,limit='100'}=req.query;
 let sql='SELECT l.*,u.name AS owner_name FROM listings l JOIN users u ON u.id=l.owner_id WHERE 1=1';const p=[];
 if(q){sql+=' AND (l.brand LIKE ? OR l.model LIKE ? OR l.description LIKE ?)';p.push(`%${q}%`,`%${q}%`,`%${q}%`);}
 for(const [key,col] of [['brand','l.brand'],['city','l.city'],['region','l.region'],['condition','l.condition'],['currency','l.currency'],['seller_name','l.seller_name']])if(typeof req.query[key]==='string'&&req.query[key]){sql+=` AND ${col}=?`;p.push(req.query[key]);}
 if(min_price!==undefined&&min_price!==''&&Number.isFinite(Number(min_price))){sql+=' AND l.price>=?';p.push(Number(min_price));}
 if(max_price!==undefined&&max_price!==''&&Number.isFinite(Number(max_price))){sql+=' AND l.price<=?';p.push(Number(max_price));}
 sql+=sort==='price_asc'?' ORDER BY l.price ASC':sort==='price_desc'?' ORDER BY l.price DESC':' ORDER BY l.created_at DESC,l.id DESC';
 sql+=' LIMIT ?';p.push(Math.max(1,Math.min(100,Number.parseInt(limit,10)||100)));
 res.json(db.prepare(sql).all(...p).map(listingOut));
});
app.get('/api/listings/:id',(req,res)=>{const id=Number(req.params.id);if(!Number.isInteger(id)||id<1)return res.status(400).json({detail:'معرف غير صالح'});db.prepare('UPDATE listings SET views=views+1 WHERE id=?').run(id);const row=listingRow(id);if(!row)return res.status(404).json({detail:'الإعلان غير موجود'});res.json(listingOut(row));});
const allowedBrands=['Apple','Samsung','Xiaomi','Huawei','Oppo','Infinix','Tecno','Nokia','أخرى'];
function validateListing(b){if(!b||typeof b!=='object')return 'بيانات الإعلان غير صالحة';if(typeof b.brand!=='string'||!allowedBrands.includes(b.brand))return 'اختر ماركة صحيحة';if(typeof b.model!=='string'||!b.model.trim()||b.model.length>100)return 'الموديل مطلوب';if(!['USD','SYP'].includes(b.currency))return 'العملة غير صحيحة';if(!Number.isFinite(Number(b.price))||Number(b.price)<=0||Number(b.price)>1e12)return 'السعر غير صالح';if(!Number.isInteger(Number(b.storage_gb))||Number(b.storage_gb)<1||Number(b.storage_gb)>2048)return 'سعة التخزين غير صحيحة';if(b.ram_gb!=null&&b.ram_gb!==''&&(!Number.isInteger(Number(b.ram_gb))||Number(b.ram_gb)<1||Number(b.ram_gb)>128))return 'الرام غير صحيحة';if(!['new','used'].includes(b.condition))return 'حالة الهاتف غير صحيحة';if(typeof b.city!=='string'||!b.city.trim()||b.city.length>80)return 'المحافظة مطلوبة';if(typeof b.seller_name!=='string'||!b.seller_name.trim()||b.seller_name.length>120)return 'اسم البائع مطلوب';if(!phoneOk(String(b.contact_phone||'')))return 'رقم التواصل غير صالح';if(typeof b.description==='string'&&b.description.length>5000)return 'الوصف طويل جداً';return null;}
function listingPayload(b,u){return {brand:b.brand,model:b.model.trim(),currency:b.currency,price:Number(b.price),storage_gb:Number(b.storage_gb),ram_gb:b.ram_gb?Number(b.ram_gb):null,condition:b.condition,city:b.city.trim(),region:b.city==='الحسكة'&&typeof b.region==='string'?b.region:null,seller_name:b.seller_name.trim(),contact_phone:String(b.contact_phone).trim(),description:typeof b.description==='string'?b.description:'',owner_id:u.id};}
app.post('/api/listings',auth,(req,res)=>{const error=validateListing(req.body);if(error)return res.status(400).json({detail:error});const b=listingPayload(req.body,req.user);const r=db.prepare(`INSERT INTO listings(owner_id,brand,model,currency,price,storage_gb,ram_gb,condition,city,region,seller_name,contact_phone,description) VALUES(@owner_id,@brand,@model,@currency,@price,@storage_gb,@ram_gb,@condition,@city,@region,@seller_name,@contact_phone,@description)`).run(b);res.status(201).json(listingOut(listingRow(Number(r.lastInsertRowid))));});
app.patch('/api/listings/:id',auth,ownedListing,(req,res)=>{const error=validateListing(req.body);if(error)return res.status(400).json({detail:error});const b=listingPayload(req.body,req.user);db.prepare(`UPDATE listings SET brand=@brand,model=@model,currency=@currency,price=@price,storage_gb=@storage_gb,ram_gb=@ram_gb,condition=@condition,city=@city,region=@region,seller_name=@seller_name,contact_phone=@contact_phone,description=@description WHERE id=@id`).run({...b,id:req.listing.id});res.json(listingOut(listingRow(req.listing.id)));});
app.patch('/api/listings/:id/sold',auth,ownedListing,(req,res)=>{db.prepare('UPDATE listings SET is_sold=CASE is_sold WHEN 0 THEN 1 ELSE 0 END WHERE id=?').run(req.listing.id);res.json(listingOut(listingRow(req.listing.id)));});
app.delete('/api/listings/:id',auth,ownedListing,(req,res)=>{db.prepare('DELETE FROM listings WHERE id=?').run(req.listing.id);res.status(204).end();});

const storage=multer.diskStorage({destination:(req,file,cb)=>cb(null,path.join(__dirname,'uploads')),filename:(req,file,cb)=>cb(null,crypto.randomUUID()+path.extname(file.originalname).toLowerCase())});
const upload=multer({storage,limits:{files:5,fileSize:5*1024*1024},fileFilter:(req,file,cb)=>{const allowed={'image/jpeg':'.jpg','image/png':'.png','image/webp':'.webp'};if(!allowed[file.mimetype])return cb(new Error('يسمح فقط بصور JPEG وPNG وWebP'));cb(null,true);}});
app.post('/api/listings/:id/images',auth,ownedListing,upload.array('files',5),(req,res)=>{const files=req.files||[];for(const f of files){const p='/uploads/'+f.filename;db.prepare('INSERT INTO listing_images(listing_id,path) VALUES(?,?)').run(req.listing.id,p);}res.json(listingOut(listingRow(req.listing.id)));});

app.get('/api/users/me/listings',auth,(req,res)=>res.json(db.prepare('SELECT * FROM listings WHERE owner_id=? ORDER BY id DESC LIMIT 100').all(req.user.id).map(listingOut)));
app.get('/api/favorites',auth,(req,res)=>res.json(db.prepare('SELECT l.* FROM listings l JOIN favorites f ON f.listing_id=l.id WHERE f.user_id=? ORDER BY f.created_at DESC').all(req.user.id).map(listingOut)));
app.post('/api/favorites/:id',auth,(req,res)=>{const id=Number(req.params.id);if(!listingRow(id))return res.status(404).json({detail:'الإعلان غير موجود'});db.prepare('INSERT OR IGNORE INTO favorites(user_id,listing_id) VALUES(?,?)').run(req.user.id,id);res.status(204).end();});
app.delete('/api/favorites/:id',auth,(req,res)=>{db.prepare('DELETE FROM favorites WHERE user_id=? AND listing_id=?').run(req.user.id,Number(req.params.id));res.status(204).end();});
app.post('/api/reports',auth,(req,res)=>{const {listing_id,reason,details=''}=req.body||{};if(!listingRow(Number(listing_id)))return res.status(404).json({detail:'الإعلان غير موجود'});if(typeof reason!=='string'||!reason.trim())return res.status(400).json({detail:'اختر سبب البلاغ'});const r=db.prepare('INSERT INTO reports(user_id,listing_id,reason,details) VALUES(?,?,?,?)').run(req.user.id,Number(listing_id),reason.slice(0,100),String(details).slice(0,2000));res.status(201).json({id:r.lastInsertRowid,message:'تم إرسال البلاغ للمراجعة'});});

app.get('/api/admin/stats',auth,admin,(req,res)=>res.json({users:db.prepare('SELECT COUNT(*) n FROM users').get().n,listings:db.prepare('SELECT COUNT(*) n FROM listings').get().n,sold:db.prepare('SELECT COUNT(*) n FROM listings WHERE is_sold=1').get().n,open_reports:db.prepare("SELECT COUNT(*) n FROM reports WHERE status='open'").get().n}));
app.get('/api/admin/users',auth,admin,(req,res)=>res.json(db.prepare('SELECT id,name,phone,role,is_active,city,shop,created_at FROM users ORDER BY id DESC LIMIT 500').all().map(u=>({...u,is_active:!!u.is_active}))));
app.patch('/api/admin/users/:id/active',auth,admin,(req,res)=>{const active=req.query.active==='true';if(Number(req.params.id)===req.user.id&&!active)return res.status(400).json({detail:'لا يمكنك تعطيل حسابك بنفسك'});db.prepare('UPDATE users SET is_active=? WHERE id=?').run(active?1:0,Number(req.params.id));audit(req.user,active?'activate_user':'disable_user','user',req.params.id);res.json({ok:true});});
app.get('/api/admin/reports',auth,admin,(req,res)=>res.json(db.prepare('SELECT * FROM reports ORDER BY id DESC LIMIT 500').all()));
app.patch('/api/admin/reports/:id',auth,admin,(req,res)=>{const status=req.query.status_value;if(!['reviewed','dismissed','open'].includes(status))return res.status(400).json({detail:'حالة البلاغ غير صحيحة'});db.prepare('UPDATE reports SET status=? WHERE id=?').run(status,Number(req.params.id));audit(req.user,'update_report','report',req.params.id);res.json({ok:true});});
app.delete('/api/admin/listings/:id',auth,admin,(req,res)=>{db.prepare('DELETE FROM listings WHERE id=?').run(Number(req.params.id));audit(req.user,'delete_listing','listing',req.params.id);res.status(204).end();});
app.get('/api/admin/actions',auth,admin,(req,res)=>res.json(db.prepare('SELECT * FROM admin_actions ORDER BY id DESC LIMIT 500').all()));

app.use((err,req,res,next)=>{console.error(err);if(res.headersSent)return next(err);if(err instanceof multer.MulterError)return res.status(400).json({detail:err.code==='LIMIT_FILE_SIZE'?'حجم الصورة أكبر من 5 ميغابايت':'عدد أو حجم الصور يتجاوز الحد المسموح'});res.status(500).json({detail:err.message==='يسمح فقط بصور JPEG وPNG وWebP'?err.message:'حدث خطأ داخلي في الخادم'});});
app.listen(PORT,'0.0.0.0',()=>console.log(`Telephone-SY يعمل على http://localhost:${PORT}`));
